// n8n Code node: Run Once for All Items
// Cleans Firecrawl search output into readable results

const SPLIT_RESULTS = true; // was false 
const MAX_DESC = 300;        // max characters per description
const TRACKING = /^(utm_.*|trk|fbclid|gclid|position|pageNum|jrtk|guid)$/i;

// Pull the JSON out of the <untrusted_data> wrapper (or accept an object as-is)
function extractJson(raw) {
  if (raw && typeof raw === 'object') return raw;
  if (typeof raw !== 'string') return null;
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  if (start === -1 || end === -1) return null;
  try {
    return JSON.parse(raw.slice(start, end + 1));
  } catch {
    return null;
  }
}

// Prefer structuredContent; fall back to the stringified content[0].text
function getWebResults(parsed) {
  const direct = parsed?.structuredContent?.data?.web;
  if (Array.isArray(direct)) return direct;
  const text = parsed?.content?.find((c) => c.type === 'text')?.text;
  return extractJson(text)?.data?.web ?? [];
}

function cleanText(str = '') {
  const s = String(str)
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1') // [text](url) -> text
    .replace(/https?:\/\/\S+/g, '')          // stray URLs
    .replace(/Skip to (content|footer)/gi, '')
    .replace(/\bView job\b/gi, '')
    .replace(/[#*`>]+/g, ' ')                // markdown symbols
    .replace(/\\+/g, ' ')                    // leftover backslashes
    .replace(/\s+/g, ' ')
    .replace(/^(\.\.\.|…)\s*/, '')
    .trim();
  return s.length > MAX_DESC ? s.slice(0, MAX_DESC).trim() + '…' : s;
}

function cleanUrl(u) {
  try {
    const url = new URL(u);
    [...url.searchParams.keys()].forEach((k) => {
      if (TRACKING.test(k)) url.searchParams.delete(k);
    });
    return url.toString();
  } catch {
    return u;
  }
}

function getDomain(u) {
  try {
    return new URL(u).hostname.replace(/^www\./, '');
  } catch {
    return '';
  }
}

const output = [];

for (const item of $input.all()) {
  const raw = item.json.Result ?? item.json.result ?? item.json;
  const parsed = extractJson(raw);

  const results = getWebResults(parsed).map((r, i) => ({
    position: r.position ?? i + 1,
    title: cleanText(r.title),
    domain: getDomain(r.url),
    url: cleanUrl(r.url),
    description: cleanText(r.description),
  }));

  if (SPLIT_RESULTS) {
    results.forEach((r) => output.push({ json: r }));
    continue;
  }

  const readable = results
    .map(
      (r) =>
        `${r.position}. ${r.title}\n   ${r.domain} | ${r.url}` +
        (r.description ? `\n   ${r.description}` : '')
    )
    .join('\n\n');

  output.push({ json: { count: results.length, results, readable } });
}

return output;

